CREATE TABLE IF NOT EXISTS money_rebalancing_plans(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,money_case_id bigint unsigned NOT NULL,name varchar(200) NOT NULL,strategy enum('NEW_MONEY','GRADUAL_TRANSFER','COMBINED','MANUAL') NOT NULL,start_date date NOT NULL,target_date date NULL,review_frequency_months smallint unsigned NULL,status enum('DRAFT','APPROVED','ACTIVE','PAUSED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'DRAFT',created_by bigint unsigned NOT NULL,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,approved_at timestamp NULL,FOREIGN KEY(money_case_id) REFERENCES money_cases(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id),CHECK(target_date IS NULL OR target_date>=start_date),CHECK(review_frequency_months IS NULL OR review_frequency_months BETWEEN 1 AND 120)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS client_care_plans(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,client_id bigint unsigned NOT NULL,advisor_id bigint unsigned NOT NULL,status enum('ACTIVE','PAUSED','ENDED') NOT NULL DEFAULT 'ACTIVE',frequency enum('MONTHLY','QUARTERLY','HALF_YEARLY','ANNUALLY','CUSTOM') NOT NULL DEFAULT 'HALF_YEARLY',custom_frequency_months smallint unsigned NULL,next_review_at datetime NULL,notes text NULL,created_by bigint unsigned NOT NULL,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id),FOREIGN KEY(advisor_id) REFERENCES users(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(client_id,status),INDEX(next_review_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS client_care_meetings(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,care_plan_id bigint unsigned NOT NULL,client_id bigint unsigned NOT NULL,advisor_id bigint unsigned NOT NULL,meeting_type varchar(50) NOT NULL,channel varchar(30) NOT NULL DEFAULT 'PERSONAL',status enum('PLANNED','CONFIRMED','COMPLETED','CANCELLED','NO_SHOW') NOT NULL DEFAULT 'PLANNED',scheduled_at datetime NOT NULL,completed_at datetime NULL,money_case_id bigint unsigned NULL,safety_case_id bigint unsigned NULL,rebalancing_plan_id bigint unsigned NULL,summary text NULL,next_meeting_at datetime NULL,created_by bigint unsigned NOT NULL,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(care_plan_id) REFERENCES client_care_plans(id),FOREIGN KEY(client_id) REFERENCES clients(id),FOREIGN KEY(advisor_id) REFERENCES users(id),FOREIGN KEY(money_case_id) REFERENCES money_cases(id) ON DELETE SET NULL,FOREIGN KEY(safety_case_id) REFERENCES safety_cases(id) ON DELETE SET NULL,FOREIGN KEY(rebalancing_plan_id) REFERENCES money_rebalancing_plans(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id),INDEX(scheduled_at,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS client_care_follow_ups(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,client_id bigint unsigned NOT NULL,advisor_id bigint unsigned NOT NULL,care_plan_id bigint unsigned NULL,meeting_id bigint unsigned NULL,money_case_id bigint unsigned NULL,safety_case_id bigint unsigned NULL,title varchar(220) NOT NULL,due_at datetime NOT NULL,status enum('OPEN','IN_PROGRESS','COMPLETED','CANCELLED') NOT NULL DEFAULT 'OPEN',completed_at datetime NULL,created_by bigint unsigned NOT NULL,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id),FOREIGN KEY(advisor_id) REFERENCES users(id),FOREIGN KEY(care_plan_id) REFERENCES client_care_plans(id) ON DELETE SET NULL,FOREIGN KEY(meeting_id) REFERENCES client_care_meetings(id) ON DELETE SET NULL,FOREIGN KEY(money_case_id) REFERENCES money_cases(id) ON DELETE SET NULL,FOREIGN KEY(safety_case_id) REFERENCES safety_cases(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id),INDEX(due_at,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
